<?php
require_once 'includes/functions.php'; require_login();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT s.*,u.name cashier FROM sales s JOIN users u ON u.id=s.user_id WHERE s.id=?');$q->execute([$id]);$sale=$q->fetch();if(!$sale){http_response_code(404);exit('Receipt not found');}$q=db()->prepare('SELECT * FROM sale_items WHERE sale_id=?');$q->execute([$id]);$items=$q->fetchAll();$page_title='Receipt';require 'includes/header.php'; ?>
<div class="receipt panel"><div class="center"><h1>POINT OF SALE</h1><p>Sales Receipt</p></div><hr><p><b>Bill No:</b> #<?= (int)$sale['id'] ?><br><b>Date:</b> <?= e($sale['sale_date']) ?><br><b>Cashier:</b> <?= e($sale['cashier']) ?><br><b>Payment:</b> <?= e($sale['payment_method']) ?></p><div class="table-wrap"><table><tr><th>Item</th><th>Price</th><th>Qty</th><th>Amount</th></tr><?php foreach($items as $it): ?><tr><td><?= e($it['product_name']) ?></td><td><?= money($it['price']) ?></td><td><?= (int)$it['quantity'] ?></td><td><?= money($it['line_total']) ?></td></tr><?php endforeach; ?></table></div><h2 class="right">Total: <?= money($sale['total_amount']) ?></h2><p class="center">Thank you for shopping!</p><div class="no-print"><button class="button" onclick="window.print()">Print receipt</button> <a class="button secondary" href="sale.php">New sale</a></div></div>
<?php require 'includes/footer.php'; ?>
